use vstd::prelude::*;

verus! {

fn solve(t: Vec<char>) -> (out: Vec<char>)
    ensures
        out.len() == t.len(),
        forall|i: int| 0 <= i < t.len() ==> out[i] == t[i],
{
    // Input is assumed non-empty, but the logic works for empty as well.
    let n = t.len();
    let mut out: Vec<char> = Vec::with_capacity(n);

    // We process elements left-to-right. A natural strictly-decreasing measure is (n - i),
    // the number of elements left to process.
    let mut i: usize = 0;
    while i < n
        invariant
            i <= n,
            out.len() == i,
            forall|k: int| 0 <= k < i ==> out[k] == t[k],
        decreases
            n - i,
    {
        // Maintain: for all k < i, out[k] == t[k]
        out.push(t[i]);
        i += 1; // n - i decreases by 1 each iteration, so the loop terminates.
    }

    out
}

} // verus!

